package com.bautruc.ecommerce.payment.api;
import com.bautruc.ecommerce.common.exception.ResourceNotFoundException;import com.bautruc.ecommerce.common.logging.LogContext;import com.bautruc.ecommerce.common.response.ApiResponse;import com.bautruc.ecommerce.common.security.*;import com.bautruc.ecommerce.common.time.BusinessClock;import com.bautruc.ecommerce.order.application.*;import com.bautruc.ecommerce.payment.api.response.PaymentResponse;import com.bautruc.ecommerce.payment.application.*;import com.bautruc.ecommerce.payment.domain.Payment;import org.springframework.security.access.AccessDeniedException;import org.springframework.web.bind.annotation.*;
@RestController public class PaymentController{private final PaymentQueryService payments;private final OrderOwnershipQuery ownership;private final CurrentUserProvider current;private final BusinessClock clock;public PaymentController(PaymentQueryService p,OrderOwnershipQuery o,CurrentUserProvider c,BusinessClock b){payments=p;ownership=o;current=c;clock=b;}@GetMapping("/api/v1/payments/{id}")public ApiResponse<PaymentResponse>detail(@PathVariable Long id){Payment p=payments.required(id);Long user=current.currentUser().orElseThrow(()->new AccessDeniedException("Authentication required")).userId();if(!ownership.isOwner(p.getOrderId(),user))throw new ResourceNotFoundException(OrderErrorCodes.ORDER_NOT_OWNER,"Payment not found for current user.");return ApiResponse.success(PaymentResponse.from(p),null,clock.businessNow().toOffsetDateTime(),LogContext.currentCorrelationId());}}
